input.script:
() => {
  const input = document.querySelector('input[name="q"]');
  if (input) {
    input.focus();
    input.value = 'Locksmiths in Texas City';
    // Try to trigger search via Google Maps internal API
    const event = new KeyboardEvent('keydown', { key: 'Enter', code: 'Enter', keyCode: 13, which: 13, bubbles: true });
    input.dispatchEvent(event);
    return { ok: true, value: input.value };
  }
  return { ok: false, error: 'no input' };
}

() => {
  // Look for any visible modals or popups
  const modals = document.querySelectorAll('[role="dialog"], [aria-modal="true"], [role="menu"]');
  const result = [];
  modals.forEach((m, i) => {
    result.push({
      index: i,
      ariaLabel: m.getAttribute('aria-label'),
      role: m.getAttribute('role'),
      visible: m.offsetWidth > 0 && m.offsetHeight > 0,
      text: m.innerText ? m.innerText.slice(0, 200) : ''
    });
  });
  // Also look for any popups
  const popups = document.querySelectorAll('.ml-promotion, .ml-promo, [data-ml-promotion]');
  popups.forEach((p, i) => {
    result.push({ popupIndex: i, text: p.innerText ? p.innerText.slice(0, 100) : '' });
  });
  return result;
}

() => {
  // Look for any visible modals or popups
  const all = document.querySelectorAll('*');
  const visible = [];
  all.forEach((el, i) => {
    if (el.tagName === 'BUTTON' && el.offsetWidth > 0 && el.offsetHeight > 0) {
      const text = (el.innerText || el.getAttribute('aria-label') || '').slice(0, 50);
      if (text && !text.includes('locksmith')) {
        visible.push({ i, tag: el.tagName, text, ariaLabel: el.getAttribute('aria-label') });
      }
    }
  });
  // Look specifically for any "now" related elements
  const nowRelated = document.body.innerHTML.match(/营业时间|现在营业|正在营业/g);
  return { buttons: visible.slice(0, 30), nowMatches: nowRelated ? nowRelated.slice(0, 10) : [] };
}

() => {
  // Find the Hours button and click it
  const spans = document.querySelectorAll('span');
  for (const s of spans) {
    if (s.innerText.trim() === 'Hours') {
      const btn = s.closest('button');
      if (btn) {
        btn.click();
        return { ok: true, clicked: true, label: btn.getAttribute('aria-label') };
      }
    }
  }
  return { ok: false, error: 'Hours button not found' };
}

() => {
  // Find any modal/dialog overlays
  const all = document.querySelectorAll('div');
  const result = [];
  all.forEach((el, i) => {
    const ariaModal = el.getAttribute('aria-modal');
    const role = el.getAttribute('role');
    if ((ariaModal === 'true' || role === 'dialog' || role === 'alertdialog') && el.offsetWidth > 0) {
      result.push({
        i, role, ariaModal,
        text: el.innerText.slice(0, 300),
        visible: true,
        rect: { w: el.offsetWidth, h: el.offsetHeight }
      });
    }
  });
  // Also check for any visible fixed/absolute positioned elements at top
  const fixedTop = [];
  document.querySelectorAll('div, section, aside').forEach(el => {
    const style = window.getComputedStyle(el);
    if ((style.position === 'fixed' || style.position === 'absolute') && el.offsetHeight > 100 && el.offsetWidth > 500) {
      const text = (el.innerText || '').slice(0, 100);
      if (text && !text.includes('Search') && !text.includes('locksmith')) {
        fixedTop.push({ position: style.position, text });
      }
    }
  });
  return { modals: result, fixedTop: fixedTop.slice(0, 5) };
}

() => {
  // Press Escape to close any dialog
  document.dispatchEvent(new KeyboardEvent('keydown', { key: 'Escape', bubbles: true }));
  // Also try to find and close any visible modals
  const closeButtons = document.querySelectorAll('button[aria-label="Close"], button[aria-label="Dismiss"]');
  let closed = 0;
  closeButtons.forEach(b => {
    if (b.offsetWidth > 0 && b.offsetHeight > 0) {
      closed++;
    }
  });
  return { closeButtonsFound: closed };
}
